        public static LocalCafeBackend Create(string path){var r=StandaloneEncounterConversationSmoke.Rules();r.goal_stages=new[]{new GoalStageRule{days=100,target=9999}};r.patron.target=.1;r.patron.destination.days=1;foreach(var m in r.patron.members){m.target=.1;m.unmatched_gain=m.gain=.1;}r.starting_funds=20000;r.dispatch_unlocks=new DispatchUnlockRule[0];r.intake.day=r.regular_introduction.day=9999;r.growth.threshold=10000;return new LocalCafeBackend(path,r);}
        static void Good(LocalCafeBackend b,string kind,string choice=null,int slot=1)=>StandaloneDispatchConversationSmoke.Good(b,kind,choice,slot:slot);
        public static void Setup(LocalCafeBackend b,bool auto=false){Good(b,"new_game","patron");foreach(string destination in new[]{"patron_visit","patron_moody_visit","patron_strict_visit"}){StandaloneDispatchConversationSmoke.Good(b,"dispatch_patron",destination,cat:"cat-tama");if(auto && destination=="patron_strict_visit"){b.Simulation.StartAutoplay("patron","clear",3);b.Simulation.Execute("day_off");var final=b.Simulation.State.dispatches.Last();b.Simulation.Execute("resolve_activity",source:final.id,choice:"receive");continue;}Good(b,"day_off");var e=b.Simulation.State.dispatches.Last();var cmd=new PythonShiftCommand{kind="receive_patron",choice=e.id,cat_id=e.cat_id,request_id=Guid.NewGuid().ToString("N"),instance_id=b.Simulation.State.instance_id,expected_revision=b.Simulation.State.revision};var payload=JsonUtility.ToJson(cmd);var reply=StandaloneDispatchConversationSmoke.Raw(b,payload);if(reply.result!=UnityEngine.Networking.UnityWebRequest.Result.Success)throw new Exception("Return failed: "+reply.error);string state=JsonUtility.ToJson(b.Simulation.State);if(StandaloneDispatchConversationSmoke.Raw(b,payload).text!=reply.text || state!=JsonUtility.ToJson(b.Simulation.State))throw new Exception("Return repeated rewards");}if(!b.Simulation.PatronWaiting)throw new Exception("Fixture failed to reach patron goal");}
        public static int BackendChecks(string path,bool restart)
        {
            int n=0;Action<bool,string> check=(ok,label)=>{n++;if(!ok)throw new Exception(label);};var b=Create(path);if(restart){Good(b,"load_game",slot:2);check(b.PatronEnding.progress.node==2,"Restart node lost");check(b.Replays.Load().entries.Any(e=>e.conversation_id==CafePatronEnding.Id),"Restart archive lost");Good(b,"load_game",slot:4);check(b.PatronEnding.progress.completed && !b.PatronEndingPending,"Restart completed ending lost");Good(b,"load_game",slot:6);check(b.PatronEnding==null,"Restart old continued save blocked");}
            bool alreadyViewed=b.Replays.Load().entries.Any(e=>e.conversation_id==CafePatronEnding.Id);Setup(b);check(b.Simulation.PatronWaiting && b.PatronEndingPending,"Final clear did not begin ending");var p=b.PatronEnding.progress;var record=JsonUtility.ToJson(CafePatronEnding.Record(b.Simulation.State));
