            int length=CafePatronEnding.Lines(CafePatronEnding.Record(b.Simulation.State),"猫").Length;
            for(int node=0;node<=length;node++){p.node=node;p.page_offset=node==4?10:0;Good(b,"save_game",slot:3);Good(b,"load_game",slot:3);p=b.PatronEnding.progress;check(p.node==node && p.page_offset==(node==4?10:0) && !p.completed && record==JsonUtility.ToJson(CafePatronEnding.Record(b.Simulation.State)),"Ending save position/result changed");}
            p.node=2;Good(b,"save_game",slot:2);check(b.Replays.Load().entries.Any(e=>e.conversation_id==CafePatronEnding.Id)==alreadyViewed,"Partial ending changed unlock");p.node=length;CafePopularityEnding.Finish(p);CafePopularityEnding.Finish(p);b.RememberViewedConversations();Good(b,"save_game",slot:4);check(b.Replays.Load().entries.Count(e=>e.conversation_id==CafePatronEnding.Id)==1,"Ending unlock duplicated");Good(b,"continue_patron");check(!b.Simulation.PatronWaiting && record==JsonUtility.ToJson(CafePatronEnding.Record(b.Simulation.State)),"Continue changed clear record");
            Good(b,"load_game",slot:4);check(b.PatronEnding.progress.completed && !b.PatronEndingPending,"Completed save reran ending");
            var old=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(path,"slot-4.json")));old.patron_ending=null;old.slot=5;File.WriteAllText(Path.Combine(path,"slot-5.json"),JsonUtility.ToJson(old));Good(b,"load_game",slot:5);check(b.PatronEndingPending,"Old pending save did not offer ending");
            old.state.patron.continued=true;old.slot=6;File.WriteAllText(Path.Combine(path,"slot-6.json"),JsonUtility.ToJson(old));Good(b,"load_game",slot:6);check(b.PatronEnding==null,"Old continued save reblocked");
            var bad=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(path,"slot-4.json")));bad.patron_ending.progress.node=999;bool rejected=false;try{CafePatronEnding.Validate(bad.patron_ending,bad.state);}catch(ArgumentException){rejected=true;}check(rejected,"Invalid node accepted");
            Good(b,"new_game","free");check(b.PatronEnding==null && b.Replays.Load().entries.Count(e=>e.conversation_id==CafePatronEnding.Id)==1,"New game lost archive or retained pending");
            // Composite simultaneous results use the existing result priority, not artificial gameplay transitions.
