            check(b.PatronEndingPending && b.PopularityEndingPending && b.View().goal_result.kind=="continue_patron","Concurrent result priority lost");
            b.PatronEnding.progress.node=7;CafePopularityEnding.Finish(b.PatronEnding.progress);Good(b,"continue_patron");check(b.PopularityEndingPending && b.View().goal_result.kind=="continue_goal","Next goal ending lost");
            var oldOnly=Create(Path.Combine(path,"legacy-only"));Good(oldOnly,"new_game","free");check(oldOnly.PatronEnding==null && !oldOnly.Replays.Load().entries.Any(e=>e.conversation_id==CafePatronEnding.Id),"Legacy data invented viewing");
            var auto=Create(Path.Combine(path,"autoplay"));Setup(auto,true);Good(auto,"step_autoplay");check(auto.PatronEndingPending && !auto.Simulation.State.autoplay.running,"Autoplay failed to terminate at ending");Good(auto,"save_game",slot:8);Good(auto,"load_game",slot:8);check(auto.PatronEndingPending && !auto.Simulation.State.autoplay.running,"Autoplay resumed on load");
            File.Copy(Path.Combine(path,"slot-6.json"),Path.Combine(path,"legacy-only/slot-6.json"),true);Good(oldOnly,"load_game",slot:6);check(oldOnly.PatronEnding==null && !oldOnly.Replays.Load().entries.Any(e=>e.conversation_id==CafePatronEnding.Id),"Old continued save invented completion");
            Setup(b);st=b.Simulation.State;st.bond_goal=new CafeBondGoal{status="cleared",resolved_day=st.day,achieved_cats=new System.Collections.Generic.List<string>{"cat-tama"}};st.clear_results.Add(new CafeClearRecord{mode="bond",day=st.day,target=1,value=1});check(b.View().required_action=="bond_result" && b.View().goal_result.kind=="continue_bond_goal","Bond/patron priority mismatch");b.BondEnding.progress.node=7;CafePopularityEnding.Finish(b.BondEnding.progress);Good(b,"continue_bond_goal");check(b.View().goal_result.kind=="continue_patron" && b.PatronEndingPending,"Patron lost after bond result");
            return n;
        }
        void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
        void Fail(Exception e){if(failed)return;failed=true;File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Debug.LogException(e);Application.Quit(1);}
        void Log(string m,string stack,LogType type){if(type==LogType.Error || type==LogType.Exception || type==LogType.Assert)Fail(new Exception(m+"\n"+stack));}
        void OnDestroy(){Application.logMessageReceived-=Log;}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--catcafe-patron-ending-check");if(i<0)return;var qa=new GameObject("Ending verification").AddComponent<StandalonePatronEndingSmoke>();DontDestroyOnLoad(qa);qa.output=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(qa.output);Application.runInBackground=true;Application.logMessageReceived+=qa.Log;try{qa.checks=BackendChecks(Path.Combine(qa.output,"cases"),args.Contains("--patron-ending-restart"));qa.StartCoroutine(qa.Guard());}catch(Exception e){qa.Fail(e);}}
        IEnumerator Guard(){var run=Run();while(true){bool more;try{more=run.MoveNext();}catch(Exception e){Fail(e);yield break;}if(!more)yield break;yield return run.Current;}}
        IEnumerator Run()
        {
            var b=Create(Path.Combine(output,"ui-"+Guid.NewGuid().ToString("N")));Setup(b);CafeBackends.UseLocal(b);SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var preview=FindObjectOfType<ContentPreview>();var ui=preview.GetComponent<PopularityEndingPanel>();Check(ui!=null && ui.Showing,"Ending not visible");var p=b.PatronEnding.progress;var priority=b.View();priority.required_action="dispatch_return";ui.Apply(priority,preview.GetComponent<PythonGoalPanel>());Check(!ui.Showing && p.node==0,"Ending ignored higher priority event");var grow=new LocalCafeBackend(Path.Combine(output,"growth-ui-"+Guid.NewGuid().ToString("N")),StandaloneGrowthBatchSmoke.Rules());Good(grow,"new_game","free");Good(grow,"day_off");var growthView=b.View();growthView.growth_choices=grow.View().growth_choices;ui.Apply(growthView,preview.GetComponent<PythonGoalPanel>());Check(!ui.Showing && p.node==0,"Ending covered growth");var pending=b.View();pending.required_action="adoption";ui.Apply(pending,preview.GetComponent<PythonGoalPanel>());Check(!ui.Showing && p.node==0,"Ending covered unanswered adoption");ui.Apply(b.View(),preview.GetComponent<PythonGoalPanel>());ui.Open();yield return null;var client=preview.GetComponent<PythonStateClient>();var actual=client.CurrentState;var otherGoal=b.View();otherGoal.goal_result.kind="continue_goal";otherGoal.goal_result.can_continue=true;typeof(PythonStateClient).GetField("current",Hidden).SetValue(client,otherGoal);Check(client.CanContinueGoal,"Bond ending blocked another goal response");typeof(PythonStateClient).GetField("current",Hidden).SetValue(client,actual);string state=JsonUtility.ToJson(b.Simulation.State);typeof(AcquisitionConversationPanel).GetField("revealed",Hidden).SetValue(ui,0f);ui.Next();ui.Next();Check(p.node==0,"Double click skipped line");yield return null;ui.Next();Check(p.node==1,"Next did not advance");ui.Close();yield return null;Check(!ui.Showing && preview.GetComponent<PythonGoalPanel>().resume.interactable,"Closed ending not resumable");preview.GetComponent<PythonGoalPanel>().Continue();yield return null;Check(ui.Showing && p.node==1,"Resume reset line");ui.Panel.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;Check(ui.HistoryScroll.content.rect.height>=ui.HistoryScroll.content.GetComponent<Text>().preferredHeight-1,"Backlog clipped");yield return null;ui.Panel.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;
            p.node=CafePatronEnding.Lines(CafePatronEnding.Record(b.Simulation.State),"猫").Length;ui.Refresh();yield return null;ui.Next();yield return null;Check(ui.Outro.activeSelf && !ui.Showing && p.completed,"Outro not shown");Check(state==JsonUtility.ToJson(b.Simulation.State),"Ending changed gameplay");Good(b,"save_game",slot:7);Good(b,"continue_patron");yield return new WaitForSecondsRealtime(2.2f);Check(!ui.Outro.activeSelf && !b.Simulation.PatronWaiting,"Continue did not close outro");Good(b,"load_game",slot:7);yield return new WaitForSecondsRealtime(2.2f);Check(ui.Outro.activeSelf && b.PatronEnding.progress.completed,"Completed result save not restored");
            SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(2);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();extra.Open();extra.Panel.transform.Find("エンディング").GetComponent<Button>().onClick.Invoke();yield return null;extra.OpenReplay(CafePatronEnding.Id+"/"+CafePopularityEnding.Branch);yield return null;Check(extra.Replay.Showing,"Ending replay locked");string before=JsonUtility.ToJson(b.Simulation.State);extra.Replay.Next();yield return null;extra.Replay.Close();Check(before==JsonUtility.ToJson(b.Simulation.State),"Replay changed gameplay");File.WriteAllText(Path.Combine(output,"result.txt"),"PASS: "+checks+" patron ending checks; zero Unity errors.");Setup(b);SceneManager.LoadScene("CatCafePythonState");
        }
